contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 amount) public {
        require(to != address(this));
        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            assert(
                amount <= balBefore &&
                c.balanceOf(address(this)) == balBefore - amount &&
                c.balanceOf(to) == toBefore + amount
            );
        } else {
            assert(amount > balBefore && c.balanceOf(address(this)) == balBefore && c.balanceOf(to) == toBefore);
        }
    }
    receive() external payable {}
}

