            ok = c.transfer(to, amount);
            reverted = false;
        }
        assert((reverted == (amount > c.balanceOf(address(this)))) && (!reverted == ok) && (!reverted || (amount > 0)) && (reverted || (c.balanceOf(address(this)) == balBefore && c.balanceOf(to) == toBefore)));
    }
    receive() external payable {}
}

