    function run(uint256 shareAmount) public payable {
        require(shareAmount < type(uint256).max);
        // A deadline strictly in the past must make sellShares revert
        // no matter what shareAmount is or what the pool state is.
        uint256 pastDeadline = block.timestamp - 1;
        bool reverted;
        try c.sellShares(shareAmount, address(this), 0, 0, "", pastDeadline) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }

    receive() external payable {}
}

